            version: AUTH_STORE_VERSION,
            profiles: {
              "openai:default": {
                type: "api_key",
                provider: "openai",
                key: "sk-test-1",
              },
            },
          },
          null,
          2,
        )}\n`,
        "utf8",
      );

      ensureAuthProfileStore(agentDir);

      fs.writeFileSync(
        authPath,
        `${JSON.stringify(
          {
            version: AUTH_STORE_VERSION,
            profiles: {
              "openai:default": {
                type: "api_key",
                provider: "openai",
                key: "sk-test-2",
              },
            },
          },
          null,
          2,
        )}\n`,
        "utf8",
